/* The tables of M42 · Dashboards and reports. */

/** One figure for one branch on one day, stored nightly so trends are fast and comparable. */
export const kpiSnapshots = defineTable(
  'kpi_snapshots',
  { module: 'M42', scope: 'org' },
  {
    ...baseColumns,
    /** a key from the catalogue */
    kpiKey: text().notNull(),
    /** empty for a group-level figure */
    branchId: uuid().references((): AnyPgColumn => branches.id),
    snapshotDate: dateStr().notNull(),
    value: decimal(18, 4).notNull(),
    /** kept so ratios can be combined across branches correctly */
    numerator: decimal(18, 4),
    denominator: decimal(18, 4),
    /** an optional breakdown key such as `{ gradeId }` */
    dims: jsonb().notNull().default({}),
    /** generated; a stable text form of `dims`, for uniqueness */
    dimsKey: text().generatedAlwaysAs((): SQL => sql`(${kpiSnapshots.dims})::text`),
  },
  (t) => [
    uniqueIndex('kpi_snapshots_kpi_key_branch_snapshot_date_dims_key_uq')
      .on(
        t.orgId,
        t.kpiKey,
        sql`coalesce(${t.branchId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
        t.snapshotDate,
        sql`coalesce(${t.dimsKey}, '')`,
      )
      .where(live(t)),
    index('kpi_snapshots_kpi_key_snapshot_date_idx').on(t.orgId, t.kpiKey, t.snapshotDate),
  ],
);

/** A report with its filters, kept by a person and optionally shared. */
export const savedReports = defineTable(
  'saved_reports',
  { module: 'M42', scope: 'org', self: 'userId' },
  {
    ...baseColumns,
    /** the owner */
    userId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    /** a report from the registry, or `analysis` for an analysis request */
    reportKey: text().notNull(),
    name: text().notNull(),
    /** valid for that report's parameter schema */
    params: jsonb().notNull(),
    isShared: boolean().notNull().default(false),
    /** with `is_shared`, the roles that can see it */
    sharedRoleKeys: text()
      .array()
      .notNull()
      .default(sql`'{}'`),
    isPinned: boolean().notNull().default(false),
  },
);

export const reportSchedules = defineTable(
  'report_schedules',
  { module: 'M42', scope: 'org' },
  {
    ...baseColumns,
    savedReportId: uuid()
      .references((): AnyPgColumn => savedReports.id)
      .notNull(),
    frequency: enumText(reportScheduleFrequencies).notNull(),
    /** for weekly */
    weekday: integer(),
    /** for monthly */
    dayOfMonth: integer(),
    sendTime: timeStr().notNull(),
    format: enumText(reportScheduleFormats).notNull(),
    /** staff of the organisation, at least one */
    recipientUserIds: uuid().array().notNull(),
    /** the report is run with this person's access */
    runAsUserId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    nextRunAt: timestamptz().notNull(),
    lastRunAt: timestamptz(),
    lastStatus: enumText(reportScheduleLastStatuses),
    isActive: boolean().notNull().default(true),
    createdBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [
    between('report_schedules', t.dayOfMonth, 1, 28),
    check('report_schedules_recipient_user_ids_some', sql`cardinality(${t.recipientUserIds}) >= 1`),
  ],
);

export const dashboardLayouts = defineTable(
  'dashboard_layouts',
  { module: 'M42', scope: 'org', self: 'userId', staff: 'read', selfAccess: 'write' },
  {
    ...baseColumns,
    portal: enumText(dashboardLayoutPortals).notNull(),
    /** a default layout for a role */
    roleKey: text(),
    /** a person's own layout; exactly one of role and user is set */
    userId: uuid().references((): AnyPgColumn => profiles.id),
    /** `{ key, x, y, w, h, params? }[]` on a 12-column grid */
    widgets: jsonb().notNull(),
  },
  (t) => [
    check(
      'dashboard_layouts_user_id_one_owner',
      sql`(${t.roleKey} is null) <> (${t.userId} is null)`,
    ),
    uniqueIndex('dashboard_layouts_portal_role_key_uq')
      .on(t.orgId, t.portal, t.roleKey)
      .where(sql`${t.deletedAt} is null and ${t.roleKey} is not null`),
    uniqueIndex('dashboard_layouts_portal_user_uq')
      .on(t.orgId, t.portal, t.userId)
      .where(sql`${t.deletedAt} is null and ${t.userId} is not null`),
  ],
);

/** Who ran which report, with what filters. For audit and for finding slow reports. */
export const reportRuns = defineTable(
  'report_runs',
  { module: 'M42', scope: 'org', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    reportKey: text().notNull(),
    /** empty for a scheduled run */
    userId: uuid().references((): AnyPgColumn => profiles.id),
    scheduleId: uuid().references((): AnyPgColumn => reportSchedules.id),
    params: jsonb().notNull(),
    /** the branches it covered */
    branchIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    rowCount: integer(),
    durationMs: integer(),
    output: enumText(reportRunOutputs).notNull(),
    status: enumText(reportRunStatuses).notNull(),
    error: text(),
  },
  (t) => [
    index('report_runs_report_key_created_at_idx').on(t.orgId, t.reportKey, t.createdAt),
    index('report_runs_user_created_at_idx').on(t.orgId, t.userId, t.createdAt),
  ],
);
